#!/usr/bin/env bash
set -euo pipefail
export PATH="/usr/local/bin:$PATH"
export DISPLAY=":$(cat "/home/runner/.local/share/omgithub-playwright/display")"
export PLAYWRIGHT_MCP_OUTPUT_DIR="/home/runner/.local/share/omgithub-playwright/output"
export OMGITHUB_CAPTURE_WEB_DIR="/home/runner/work/_temp/omgithub-web"
export OMGITHUB_PLAYWRIGHT_ROOT="/home/runner/.local/share/omgithub-playwright"
export NODE_OPTIONS="--require=/home/runner/.local/share/omgithub-playwright/wip-screenshot-hook.cjs ${NODE_OPTIONS:-}"
for arg in "$@"; do
  case "$arg" in
    -*) continue ;;
    open) exec "/home/runner/.local/share/omgithub-playwright/node_modules/.bin/playwright-cli" "$@" --config "/home/runner/.local/share/omgithub-playwright/linux.json" ;;
    *) break ;;
  esac
done
exec "/home/runner/.local/share/omgithub-playwright/node_modules/.bin/playwright-cli" "$@"
const { join } = require('node:path')
try {
  if (process.env.OMGITHUB_CAPTURE_WEB_DIR || process.env.OPENCODE_WEB_DIR) {
    const runtime = process.env.OMGITHUB_PLAYWRIGHT_ROOT || __dirname
    const core = require(require.resolve('playwright-core', { paths: [join(runtime, 'node_modules/@playwright/cli')] }))
    require('./wip-screenshots.cjs').instrument(core, { ...process.env,
      OMGITHUB_BROWSER_SESSION: process.argv[1]?.endsWith('cliDaemon.js') ? process.argv[2] || '' : process.env.OMGITHUB_BROWSER_SESSION || '' })
  }
} catch (error) { console.error('WIP screenshot instrumentation unavailable:', error.message) }

