const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:'/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome', args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1200,height:900}, deviceScaleFactor:1});
  const errors=[];
  page.on('pageerror', e=>errors.push(e.message));
  page.on('console', m=>{if(m.type()==='error')errors.push(m.text())});
  await page.goto('http://localhost:3000', {waitUntil:'networkidle'});
  console.log('title:', await page.title());
  console.log('canvas:', await page.locator('#game').evaluate(el=>({width:el.width,height:el.height,css:el.getBoundingClientRect().toJSON()})));
  await page.locator('#start-btn').click();
  await page.waitForTimeout(600);
  await page.keyboard.press('e');
  await page.waitForTimeout(200);
  await page.keyboard.press('i');
  const modalOpen=await page.locator('#modal-backdrop').evaluate(el=>el.classList.contains('open'));
  await page.keyboard.press('Escape');
  await page.keyboard.press('c');
  const statsOpen=await page.locator('#modal-title').innerText();
  await page.keyboard.press('Escape');
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/ashenvale-check.jpg',type:'jpeg',quality:78});
  console.log('inventory modal:',modalOpen,'character modal:',statsOpen);
  console.log('runtime errors:',JSON.stringify(errors));
  console.log('quest:',await page.locator('#quest-title').innerText(),await page.locator('#quest-desc').innerText());
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

